import{_ as a,o,c as t,ag as n}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"0054 — Standard-service identifiers are open and integrations are Host-owned","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0054-standard-service-identifiers-are-open-and-host-integrated.md","filePath":"spec/decisions/0054-standard-service-identifiers-are-open-and-host-integrated.md"}'),i={name:"spec/decisions/0054-standard-service-identifiers-are-open-and-host-integrated.md"};function s(r,e,d,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="_0054-—-standard-service-identifiers-are-open-and-integrations-are-host-owned" tabindex="-1">0054 — Standard-service identifiers are open and integrations are Host-owned <a class="header-anchor" href="#_0054-—-standard-service-identifiers-are-open-and-integrations-are-host-owned" aria-label="Permalink to &quot;0054 — Standard-service identifiers are open and integrations are Host-owned&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-08-23</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./0043-forms-target-popular-vendor-locked-primitives.html">Decision 0043</a> correctly separates established standard data planes from lifecycle Forms, and <a href="./0045-external-standard-services-are-sealed-slots.html">decision 0045</a> correctly keeps endpoints and credentials behind a sealed slot. Their first concrete contract, however, made two details Takoform-owned that do not belong here:</p><ol><li><code>standards.takoform.com/v1alpha1</code> enumerates four protocol names, so a Form cannot request a standard Takoform did not know when that schema shipped.</li><li>Takoform fixes environment members for each protocol, so adding or evolving an integration requires a Takoform release even though the protocol and the Host implementation own those entries.</li></ol><p>This couples an external standard&#39;s identity and runtime integration to the Takoform registry and release cadence. It also makes schema acceptance look like protocol certification, which a structural schema cannot provide.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The current StandardServiceRef is <code>standards.takoform.com/v1</code> and contains:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;standards.takoform.com/v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.amazonaws.s3&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>protocol</code> is an opaque, case-sensitive, normalized reverse-DNS owner namespace followed by a protocol segment. The schema constrains only that grammar and a 253-character bound. Takoform maintains no enum or registry. A previously unknown but grammar-valid identifier is valid Form data; its presence is not a claim or certification that any implementation conforms to that protocol.</p><p>A Host integration plugin owns exact protocol support and runtime materialization. Its <code>StandardServiceSupport</code> profile echoes the exact <code>{apiVersion, protocol}</code> and states tenant satisfiability. A required slot is accepted only with an exact satisfiable answer; an unknown, missing, or mismatched profile fails closed.</p><p>Takoform guarantees one sealed runtime-native binding keyed by the slot&#39;s <code>name</code>. The Host integration and protocol own the binding&#39;s internal entries, delivery mechanism, endpoint layout, and credential shape. Takoform defines no protocol-to-environment-variable or filesystem-projection table. Collision is generic over the slot binding name and the runtime&#39;s other binding names.</p><p>The slot remains <code>{name, service, required?}</code>. It gains no Resource selector, endpoint, credential, provider, or arbitrary entry map. <code>required</code> continues to default to true; optional unsatisfied slots project no binding.</p><p>This contract is introduced only with the stable <code>forms.takoform.com/v1</code> Host lane and stable Form Definition profile. The occupied <code>forms.takoform.com/v1beta4</code> Host documents, support profile, and conformance corpus retain their original v1alpha1 standard-service reference.</p><h2 id="superseded-portions" tabindex="-1">Superseded portions <a class="header-anchor" href="#superseded-portions" aria-label="Permalink to &quot;Superseded portions&quot;">​</a></h2><p>This decision supersedes only:</p><ul><li>decision 0043&#39;s closed Takoform protocol vocabulary and reviewed-widening requirement; and</li><li>decision 0045&#39;s closed vocabulary and protocol-specific projected-member table.</li></ul><p>Their remaining boundary stays accepted: categories with established standards are integrated rather than respecified as Forms, and portable state contains no endpoint or credential.</p><p><code>standard-service-ref-v1alpha1.schema.json</code> and its four bare protocol values remain immutable published history. They are not widened or reinterpreted.</p><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to &quot;Enforcement&quot;">​</a></h2><ul><li>The v1 StandardServiceRef schema has a pattern and bound, and no enum.</li><li>Stable-v1 Form schemas embed the exact v1 apiVersion and annotation.</li><li>Model and provider round trips preserve unknown grammar-valid identifiers.</li><li>Provider/Host support lookup compares the complete serviceRef and fails closed for an unsupported required slot.</li><li>Portable conformance tests generic sealing, slot-name collision, exact unsupported-protocol refusal, and readiness. Protocol-specific projections belong to each Host integration&#39;s own tests.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>A new standard can be integrated by its namespace owner and a Host without a Takoform schema release. Takoform still gives authors a typed, bounded, non-secret declaration and still makes unsupported required capability visible before mutation. The cost is intentional: portable code cannot assume a Takoform-defined set of environment members for a protocol; it consumes the runtime-native binding contract supplied by the integration it selected.</p>`,23)])])}const u=a(i,[["render",s]]);export{m as __pageData,u as default};
